package edu.pe.cibertec.saibm.inventario;
import static org.assertj.core.api.Assertions.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test; import edu.pe.cibertec.saibm.inventario.application.port.out.InventoryStorePort; import edu.pe.cibertec.saibm.inventario.application.port.in.InventoryUseCase; import edu.pe.cibertec.saibm.inventario.application.usecase.InventoryService; import edu.pe.cibertec.saibm.inventario.domain.event.InventoryEvent; import edu.pe.cibertec.saibm.inventario.domain.model.*; import edu.pe.cibertec.saibm.inventario.domain.service.*; import edu.pe.cibertec.saibm.inventario.domain.exception.InventoryConflictException;
class InventoryDomainTest {
 @Test void stockNeverGoesNegativeAndReleaseRestoresAvailability(){var s=new Stock("book-7",2,2);assertThat(s.reserve(3)).isFalse();assertThat(s.availableStock()).isEqualTo(2);assertThat(s.reserve(1)).isTrue();s.release(1);assertThat(s.availableStock()).isEqualTo(2);}
 @Test void stateMachineExpiresReleaseButRejectsExpiredCommit(){var m=new InventoryStateMachine();assertThat(m.transition(InventoryState.HELD,InventoryOperation.RELEASE,Instant.MIN,Instant.now())).isEqualTo(InventoryState.EXPIRED);assertThatThrownBy(()->m.transition(InventoryState.HELD,InventoryOperation.COMMIT,Instant.MIN,Instant.now())).isInstanceOf(InventoryConflictException.class);}
 @Test void holdReplayIsIdempotentAndPayloadConflictIsRejected(){var store=new Store();InventoryUseCase use=new InventoryService(store);var expiry=Instant.now().plusSeconds(60);var first=use.hold("book-7",1,expiry,"same","c1");var replay=use.hold("book-7",1,expiry,"same","c1");assertThat(first.view()).isEqualTo(replay.view());assertThat(store.events).hasSize(1);assertThatThrownBy(()->use.hold("book-7",2,expiry,"same","c1")).isInstanceOf(InventoryConflictException.class);}
 static final class Store implements InventoryStorePort {final Map<String,Stock> stocks=new HashMap<>(Map.of("book-7",new Stock("book-7",2,2)));final Map<String,Hold> holds=new HashMap<>();final List<InventoryEvent> events=new ArrayList<>();public Optional<Stock> stockForUpdate(String id){return Optional.ofNullable(stocks.get(id));}public Optional<Hold> holdForUpdate(String k){return Optional.ofNullable(holds.get(k));}public boolean insert(Hold h){if(holds.putIfAbsent(h.operationKey(),h)!=null)return false;return true;}public void save(Stock s){stocks.put(s.bookId(),s);}public void save(Hold h){holds.put(h.operationKey(),h);}public void movement(InventoryMovement m){}public void outbox(InventoryEvent e){events.add(e);}}
}
